// ❌ OLD: Rendering a modal inside a parent with overflow: hidden or transform
// clips the modal or breaks its fixed positioning.
export default function Card() {
  return (
    <div style={{ overflow: 'hidden', height: '150px', border: '1px solid black' }}>
      <h3>Card Title</h3>
      {/* ❌ Modal is visually trapped and cut off inside the 150px box: */}
      <div style={{ position: 'fixed', top: '20%', left: '20%', width: '400px', background: 'white' }}>
        Trapped Modal Content
      </div>
    </div>
  );
}

import { createPortal } from 'react-dom';

function ModalContent({ onClose }) {
  return (
    <div className="modal-overlay" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)' }}>
      <div className="modal-body" style={{ background: 'white', padding: '20px' }}>
        <h2>Modal Title</h2>
        <button onClick={onClose}>Close</button>
      </div>
    </div>
  );
}

export default function Card() {
  return (
    // ✅ Parent onClick catches bubbling events from the portal even though DOM is in document.body!
    <div
      onClick={() => console.log('Click bubbled to Card virtual parent!')}
      style={{ overflow: 'hidden', height: '150px' }}
    >
      <h3>Card Content</h3>
      {createPortal(<ModalContent onClose={() => {}} />, document.body)}
    </div>
  );
}
